import{_ as p,a0 as r,w as l,s as o,ao as h,I as t,x as a,a1 as n,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"如何使用 virsh 命令創建、還原和刪除 KVM 虛擬機快照 | LCTT x X-CMD","titleTemplate":false,"description":"如何使用 virsh 命令創建、還原和刪除 KVM 虛擬機快照 | LCTT (201805) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用 virsh 命令創建、還原和刪除 KVM 虛擬機快照 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用 virsh 命令創建、還原和刪除 KVM 虛擬機快照 | LCTT (201805) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201805/20180205 How to Create, Revert and Delete KVM Virtual machine snapshot with virsh command","title":"如何使用 virsh 命令創建、還原和刪除 KVM 虛擬機快照","tag":"201805","desc":""},"relativePath":"201805/20180205 How to Create, Revert and Delete KVM Virtual machine snapshot with virsh command.md","filePath":"[post].md"}'),d={name:"201805/20180205 How to Create, Revert and Delete KVM Virtual machine snapshot with virsh command.md"};function c(g,s,m,v,k,u){const e=r("Link");return l(),o("div",null,[s[13]||(s[13]=h(`<h1 id="如何使用-virsh-命令創建、還原和刪除-kvm-虛擬機快照" tabindex="-1">如何使用 virsh 命令創建、還原和刪除 KVM 虛擬機快照 <a class="header-anchor" href="#如何使用-virsh-命令創建、還原和刪除-kvm-虛擬機快照" aria-label="Permalink to “如何使用 virsh 命令創建、還原和刪除 KVM 虛擬機快照”">​</a></h1><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/02/KVM-VirtualMachine-Snapshot.jpg" alt="KVM-VirtualMachine-Snapshot"></p><p>在虛擬化平台上進行系統管理工作時，經常需要在開始重大操作比如部署補丁和代碼前先設置一個虛擬機<ruby>快照<rt>snapshot</rt></ruby>。</p><p>虛擬機<strong>快照</strong>是特定時間點的虛擬機磁盤的副本。換句話説，快照保存了給定的時間點虛擬機的狀態和數據。</p><h3 id="我們可以在哪裏使用虛擬機快照" tabindex="-1">我們可以在哪裏使用虛擬機快照？ <a class="header-anchor" href="#我們可以在哪裏使用虛擬機快照" aria-label="Permalink to “我們可以在哪裏使用虛擬機快照？”">​</a></h3><p>如果你在使用基於 <strong>KVM</strong> 的<strong>虛擬機管理程序</strong>，那麼可以使用 <code>virsh</code> 命令獲取虛擬機或域快照。快照在一種情況下變得非常有用，當你已經在虛擬機上安裝或應用了最新的補丁，但是由於某些原因，虛擬機上的程序變得不穩定，開發團隊想要還原所有的更改和補丁。如果你在應用補丁之前設置了虛擬機的快照，那麼可以使用快照將虛擬機恢復到之前的狀態。</p><p><strong>注意：</strong>我們只能對磁盤格式為 <strong>Qcow2</strong> 的虛擬機的進行快照，並且 kvm 的 <code>virsh</code> 命令不支持 raw 磁盤格式，請使用以下命令將原始磁盤格式轉換為 qcow2。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># qemu-img convert -f raw -O qcow2 image-name.img image-name.qcow2</span></span></code></pre></div><h3 id="創建-kvm-虛擬機-域-快照" tabindex="-1">創建 KVM 虛擬機（域）快照 <a class="header-anchor" href="#創建-kvm-虛擬機-域-快照" aria-label="Permalink to “創建 KVM 虛擬機（域）快照”">​</a></h3><p>我假設 KVM 管理程序已經在 CentOS 7 / RHEL 7 機器上配置好了，並且有虛擬機正在運行。我們可以使用下面的 <code>virsh</code> 命令列出虛擬機管理程序中的所有虛擬機，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@kvm-hypervisor ~]# virsh list --all</span></span>
<span class="line"><span> Id    Name                           State</span></span>
<span class="line"><span>----------------------------------------------------</span></span>
<span class="line"><span> 94    centos7.0                      running</span></span>
<span class="line"><span> 101   overcloud-controller           running</span></span>
<span class="line"><span> 102   overcloud-compute2             running</span></span>
<span class="line"><span> 103   overcloud-compute1             running</span></span>
<span class="line"><span> 114   webserver                      running</span></span>
<span class="line"><span> 115   Test-MTN                       running</span></span></code></pre></div><p>假設我們想創建 webserver 虛擬機的快照，運行下面的命令，</p><p><strong>語法：</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># virsh snapshot-create-as –domain {vm_name} –name {snapshot_name} –description “enter description here”</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@kvm-hypervisor ~]# virsh snapshot-create-as --domain webserver --name webserver_snap --description &quot;snap before patch on 4Feb2018&quot;</span></span>
<span class="line"><span>Domain snapshot webserver_snap created</span></span></code></pre></div><p>創建快照後，我們可以使用下面的命令列出與虛擬機相關的快照：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@kvm-hypervisor ~]# virsh snapshot-list webserver</span></span>
<span class="line"><span> Name                 Creation Time             State</span></span>
<span class="line"><span>------------------------------------------------------------</span></span>
<span class="line"><span> webserver_snap       2018-02-04 15:05:05 +0530 running</span></span>
<span class="line"><span>[root@kvm-hypervisor ~]#</span></span></code></pre></div><p>要列出虛擬機快照的詳細信息，請運行下面的 <code>virsh</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@kvm-hypervisor ~]# virsh snapshot-info --domain webserver --snapshotname webserver_snap</span></span>
<span class="line"><span>Name:           webserver_snap</span></span>
<span class="line"><span>Domain:         webserver</span></span>
<span class="line"><span>Current:        yes</span></span>
<span class="line"><span>State:          running</span></span>
<span class="line"><span>Location:       internal</span></span>
<span class="line"><span>Parent:         -</span></span>
<span class="line"><span>Children:       0</span></span>
<span class="line"><span>Descendants:    0</span></span>
<span class="line"><span>Metadata:       yes</span></span></code></pre></div><p>我們可以使用下面的 <code>qemu-img</code> 命令查看快照的大小：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@kvm-hypervisor ~]# qemu-img info /var/lib/libvirt/images/snaptestvm.img</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/02/qemu-img-command-output-kvm.jpg" alt="qemu-img-command-output-kvm"></p><h3 id="還原-kvm-虛擬機快照" tabindex="-1">還原 KVM 虛擬機快照 <a class="header-anchor" href="#還原-kvm-虛擬機快照" aria-label="Permalink to “還原 KVM 虛擬機快照”">​</a></h3><p>假設我們想要將 webserver 虛擬機還原到我們在上述步驟中創建的快照。使用下面的 <code>virsh</code> 命令將 Webserver 虛擬機恢復到其快照 webserver_snap 時。</p><p><strong>語法：</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># virsh snapshot-revert {vm_name} {snapshot_name}</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@kvm-hypervisor ~]# virsh snapshot-revert webserver webserver_snap</span></span></code></pre></div><h3 id="刪除-kvm-虛擬機快照" tabindex="-1">刪除 KVM 虛擬機快照 <a class="header-anchor" href="#刪除-kvm-虛擬機快照" aria-label="Permalink to “刪除 KVM 虛擬機快照”">​</a></h3><p>要刪除 KVM 虛擬機快照，首先使用 <code>virsh snapshot-list</code> 命令獲取虛擬機的快照詳細信息，然後使用 <code>virsh snapshot-delete</code> 命令刪除快照。如下示例所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@kvm-hypervisor ~]# virsh snapshot-list --domain webserver</span></span>
<span class="line"><span> Name                 Creation Time             State</span></span>
<span class="line"><span>------------------------------------------------------------</span></span>
<span class="line"><span> webserver_snap       2018-02-04 15:05:05 +0530 running</span></span>
<span class="line"><span>[root@kvm-hypervisor ~]# virsh snapshot-delete --domain webserver --snapshotname webserver_snap</span></span>
<span class="line"><span>Domain snapshot webserver_snap deleted</span></span></code></pre></div><p>這就是本文的全部內容，我希望你們能夠了解如何使用 <code>virsh</code> 命令來管理 KVM 虛擬機快照。請分享你的反饋，並不要猶豫地分享給你的技術朋友🙂</p><hr>`,32)),t("p",null,[s[1]||(s[1]=a("via: ",-1)),n(e,{href:"https://www.linuxtechi.com/create-revert-delete-kvm-virtual-machine-snapshot-virsh-command/"},{default:i(()=>[...s[0]||(s[0]=[a("https://www.linuxtechi.com/create-revert-delete-kvm-virtual-machine-snapshot-virsh-command/",-1)])]),_:1})]),t("p",null,[s[5]||(s[5]=a("作者：",-1)),n(e,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:i(()=>[...s[2]||(s[2]=[a("Pradeep Kumar",-1)])]),_:1}),s[6]||(s[6]=a(" 譯者：",-1)),n(e,{href:"https://github.com/geekpi"},{default:i(()=>[...s[3]||(s[3]=[a("geekpi",-1)])]),_:1}),s[7]||(s[7]=a(" 校對：",-1)),n(e,{href:"https://github.com/wxy"},{default:i(()=>[...s[4]||(s[4]=[a("wxy",-1)])]),_:1})]),t("p",null,[s[10]||(s[10]=a("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[8]||(s[8]=[a("LCTT",-1)])]),_:1}),s[11]||(s[11]=a(" 原創編譯，",-1)),n(e,{href:"https://linux.cn/"},{default:i(()=>[...s[9]||(s[9]=[a("Linux中國",-1)])]),_:1}),s[12]||(s[12]=a(" 榮譽推出",-1))])])}const y=p(d,[["render",c]]);export{w as __pageData,y as default};
